  run:(method,args)=>{const allow=['aid','build','repayArrears','tax','train','recruit','forge','appoint','governor','caseAction','decide','diplomacy','exploreTile','examChoose','selectionChoose','selectionDismiss','selectionClose','incidentResolve','prepareDefense','dismissConsort','interact','gift','practice','agency','outing','childCare','succession','suppress'];if(allow.includes(method))act(method,args,()=>{if(method==='decide'){const story=s.stories.find(st=>st.id===args[0]);if(ui.modal?.type==='story')ui.modal={type:'storyHistory',id:story.id};}if(method==='incidentResolve'&&ui.modal?.type==='incident')close();if(method==='succession')close();});},
  story:id=>open('story',id),storyHistory:id=>open('storyHistory',id),constructionRegion:id=>{ui.modal.id=id;ui.lastFeedback='';renderModal();},picker:(mode,target)=>open('picker',null,{mode,target}),pickPerson:id=>{const m=ui.modal;if(m.mode==='office')act('appoint',[m.target,id]);else if(m.mode==='governor')act('governor',[m.target,id]);else if(m.mode==='gift')act('gift',[id,m.target],()=>{ui.modal={type:'treasures'};});else if(m.mode==='investigate')act('agency',['investigate',id]);else if(m.mode==='agency-appoint')act('agency',['appoint',id]);},tutorialDismiss:()=>{s.flags.tutorialDone=true;save();close();render();toast('已跳过，可在「玩法」重开。');},
  endPhase:()=>{if(s.lost){open('settings');return;}if(s.phase==='court')act('endCourt',[],()=>{ui.tab='内';ui.selected=null;});else act('nextTurn',[],()=>{ui.tab='策';ui.selected=null;ui.mapReady=false;if(game.caseReports().length)ui.modal={type:'caseReports'};});},
  selectCountry:id=>{close();if(s.phase!=='court'){toast('请下月上朝时处理外交。');return;}ui.selected={kind:'country',id};render();},countryWar:id=>{const co=s.countries.find(c=>c.id===id);if(co?.war)act('diplomacy',[id,'peace']);else open('warConfirm',id);},warExecute:id=>act('diplomacy',[id,'war'],close),confirmCase:id=>open('caseConfirm',id),caseExecute:id=>act('caseAction',[id,'punish'],()=>{ui.modal={type:'cases'};}),caseInvestigate:id=>act('caseAction',[id,'investigate']),succession:id=>open('succession',id),export:exportSave,import:()=>$('import-file')?.click(),resetConfirm:()=>open('resetConfirm'),reset:()=>{try{localStorage.setItem(KEY+'-before-reset',JSON.stringify(s));}catch{}game=new LiangGame();s=game.s;ui.tab='策';ui.selected=null;ui.mapReady=false;ui.lastFeedback='';save();render();open('intro');}
